const listParticipantsByContest = `-- name: ListParticipantsByContest :many
SELECT
    cp.id,
    cp.contest_id,
    cp.user_id,
    COALESCE(u.name, 'Пользователь ' || cp.user_id::text) AS user_name,
    cp.pet_name,
    cp.pet_description,
    cp.entry_title,
    cp.entry_description,
    cp.author_name,
    cp.registration_answers,
    cp.nomination_id,
    cp.submission_status,
    cp.submission_comment,
    COALESCE(cc.comment_cnt, 0)::bigint AS comment_count,
    cp.created_at,
    cp.updated_at
FROM contest_participants cp
LEFT JOIN users u ON u.user_id = cp.user_id
LEFT JOIN (
    SELECT participant_id, COUNT(*)::bigint AS vote_cnt
    FROM contest_votes
    GROUP BY participant_id
) vc ON vc.participant_id = cp.id
LEFT JOIN (
    SELECT participant_id, COALESCE(SUM(score), 0)::bigint AS jury_sum
    FROM contest_jury_scores
    GROUP BY participant_id
) js ON js.participant_id = cp.id
LEFT JOIN (
    SELECT participant_id, COUNT(*)::bigint AS comment_cnt
    FROM contest_comments
    GROUP BY participant_id
) cc ON cc.participant_id = cp.id
WHERE cp.contest_id = $1
  AND (
    cp.submission_status = 'accepted'
    OR $2::boolean = true
    OR (
      $3::bigint IS NOT NULL
      AND cp.user_id = $3::bigint
    )
  )
  AND (
    $4::text = 'all'
    OR ($4::text = 'none' AND cp.nomination_id IS NULL)
    OR (
      $4::text = 'id'
      AND cp.nomination_id = $5::uuid
    )
  )
  AND (
    NOT $6::boolean
    OR $3::bigint IS NULL
    OR (
      (SELECT COUNT(*)::int FROM contest_jury_criteria cjc WHERE cjc.contest_id = cp.contest_id) = 0
    )
    OR (
      (SELECT COUNT(*)::int FROM contest_jury_scores j
       WHERE j.participant_id = cp.id AND j.user_id = $3::bigint
      ) < (
      SELECT COUNT(*)::int FROM contest_jury_criteria cjc2 WHERE cjc2.contest_id = cp.contest_id
      )
    )
  )
  AND (
    $7::text = 'all'
    OR (
      $3::bigint IS NOT NULL
      AND cp.user_id = $3::bigint
    )
  )
  AND (
    $8::text = 'all'
    OR ($8::text = 'accepted' AND cp.submission_status = 'accepted')
    OR ($8::text = 'pending' AND cp.submission_status = 'pending')
    OR ($8::text = 'rejected' AND cp.submission_status = 'rejected')
    OR (
      $8::text = 'non_accepted'
      AND cp.submission_status IN ('pending', 'rejected')
    )
  )
  AND (
    NOT $9::boolean
    OR EXISTS (
      SELECT 1 FROM contest_votes v
      WHERE v.contest_id = cp.contest_id
        AND v.participant_id = cp.id
        AND v.user_id = $3::bigint
    )
  )
  AND (
    NOT $10::boolean
    OR (
      $3::bigint IS NOT NULL
      AND EXISTS (
        SELECT 1 FROM contest_user_participant_favorites f
        WHERE f.participant_id = cp.id
          AND f.user_id = $3::bigint
      )
    )
  )
ORDER BY
  CASE WHEN $11::text = 'votes' THEN COALESCE(vc.vote_cnt, 0::bigint) END DESC NULLS LAST,
  CASE WHEN $11::text = 'jury' THEN COALESCE(js.jury_sum, 0::bigint) END DESC NULLS LAST,
  CASE WHEN $11::text = 'comments' THEN COALESCE(cc.comment_cnt, 0::bigint) END DESC NULLS LAST,
  CASE WHEN $11::text = 'created_at' THEN cp.created_at END DESC NULLS LAST,
  cp.id ASC
LIMIT $13::int OFFSET $12::int
`

